import {FlightTrails} from './flight-trails.js';
import {drawPlaneNames,planeMembershipGrade} from './plane-nameplates.js';
import * as T from './vendor/three.module.min.js';
import {TRACK,HOMES,coord,FINISH} from './engine.js';
import {PALETTE} from './palette.js';
export {PALETTE} from './palette.js';
const material=(color,roughness=.35)=>new T.MeshStandardMaterial({color,roughness,metalness:.04});
const white=material(0xf7fbff),navy=material(0x143858),rubber=material(0x26415a),glass=material(0xb9e6ff,.18);
function shape(w,d,r){const s=new T.Shape(),x=-w/2,z=-d/2;s.moveTo(x+r,z);s.lineTo(x+w-r,z);s.quadraticCurveTo(x+w,z,x+w,z+r);s.lineTo(x+w,z+d-r);s.quadraticCurveTo(x+w,z+d,x+w-r,z+d);s.lineTo(x+r,z+d);s.quadraticCurveTo(x,z+d,x,z+d-r);s.lineTo(x,z+r);s.quadraticCurveTo(x,z,x+r,z);return s;}
function box(w,h,d,mat,r=.1){const g=new T.ExtrudeGeometry(shape(w,d,Math.min(r,w/2,d/2)),{depth:h,bevelEnabled:false,curveSegments:5,steps:1});g.rotateX(-Math.PI/2);const m=new T.Mesh(g,mat);m.castShadow=true;m.receiveShadow=true;return m;}
function sphere(x,y,z,sx,sy,sz,mat){const m=new T.Mesh(new T.SphereGeometry(1,24,16),mat);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;return m;}
function tilePoint([x,z]){return new T.Vector3((x-7)*.72,.23,(z-7)*.72);}
const baseCenters=[[-3.7,-3.7],[3.7,-3.7],[3.7,3.7],[-3.7,3.7]];
export function basePosition(color,piece){const c=baseCenters[color];return new T.Vector3(c[0]+(piece===0?-.62:.62),.28,c[1]);}
export function planePosition(color,piece,p){if(p<0)return basePosition(color,piece);if(p>=FINISH)return new T.Vector3((color%2?1:-1)*.27,.35,(color<2?-1:1)*(.25+piece*.28));return tilePoint(coord(color,p));}
export function makePlane(color){
 const group=new T.Group(),body=new T.Group(),mat=material(PALETTE[color],.22);group.add(body);
 body.add(sphere(0,.39,.05,.30,.32,.47,mat));
 body.add(sphere(0,.31,-.25,.275,.24,.25,white));
 const wing=box(1.34,.1,.34,mat,.15);wing.position.set(0,.29,-.025);body.add(wing);
 for(const x of [-.47,.47]){const stripe=box(.12,.012,.3,white,.02);stripe.position.set(x,.402,-.025);body.add(stripe);}
 const tail=box(.65,.07,.23,mat,.08);tail.position.set(0,.45,.37);body.add(tail);
 const fin=box(.09,.43,.28,mat,.04);fin.position.set(0,.43,.35);body.add(fin);
 body.add(sphere(0,.57,-.12,.255,.18,.25,glass));
 for(const x of [-.115,.115]){body.add(sphere(x,.56,-.32,.103,.12,.045,white));body.add(sphere(x+.008,.55,-.362,.05,.068,.02,navy));body.add(sphere(x-.006,.58,-.383,.017,.021,.009,white));}
 const smile=new T.Mesh(new T.TorusGeometry(.08,.014,6,24,Math.PI),navy);smile.rotation.z=Math.PI;smile.position.set(0,.265,-.466);body.add(smile);
 const propeller=new T.Group();propeller.position.set(0,.32,-.56);
 for(const angle of [0,Math.PI*2/3,Math.PI*4/3]){const blade=box(.09,.025,.37,mat,.04);blade.rotation.x=Math.PI/2;blade.rotation.z=angle;propeller.add(blade);}
 body.add(propeller);body.add(sphere(0,.32,-.59,.082,.082,.04,material(0xffce4a,.22)));
 for(const x of [-.23,.23]){const wheel=new T.Mesh(new T.CylinderGeometry(.092,.092,.065,20),rubber);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.09,.08);body.add(wheel);const cap=new T.Mesh(new T.CylinderGeometry(.05,.05,.071,16),white);cap.rotation.z=Math.PI/2;cap.position.copy(wheel.position);body.add(cap);}
 const marker=new T.Mesh(new T.RingGeometry(.48,.52,40),new T.MeshBasicMaterial({color:0xffdf7b,transparent:true,opacity:.9,side:T.DoubleSide}));marker.rotation.x=-Math.PI/2;marker.position.y=.018;marker.visible=false;group.add(marker);group.userData={body,propeller,marker,color};return group;
}
export class BoardScene{
 constructor(wrap,onSelect,{reduced=false}={}){this.wrap=wrap;this.onSelect=onSelect;this.reduced=reduced;this.scene=new T.Scene();this.camera=new T.PerspectiveCamera(34,1,.1,100);this.camera.position.set(0,17.7,13.8);this.camera.lookAt(0,0,.1);this.scene.fog=new T.Fog(0xe4f2fc,30,60);this.renderer=new T.WebGLRenderer({antialias:true,alpha:true,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.25;wrap.appendChild(this.renderer.domElement);this.cosmeticTrails=new FlightTrails();this.effectCanvas=document.createElement('canvas');this.effectCanvas.className='flight-trail-overlay';this.effectCanvas.setAttribute('aria-hidden','true');wrap.appendChild(this.effectCanvas);this.effectContext=this.effectCanvas.getContext('2d');this.renderer.domElement.setAttribute('aria-label','Interactive 3D flight board. You may also choose planes using the buttons.');this.scene.add(new T.HemisphereLight(0xf3faff,0x8da7c1,2.6));const light=new T.DirectionalLight(0xfff7e8,3.6);light.position.set(-7,15,7);light.castShadow=true;light.shadow.mapSize.set(2048,2048);Object.assign(light.shadow.camera,{left:-10,right:10,top:10,bottom:-10});light.shadow.normalBias=.03;this.scene.add(light);this.scene.add(new T.AmbientLight(0xffffff,.4));this.planes=[];this.selectable=[];this.anims=[];this.particles=[];this.buildBoard();this.ray=new T.Raycaster();this.pointer=new T.Vector2();this.renderer.domElement.addEventListener('pointerup',e=>this.click(e));this.resizeObserver=new ResizeObserver(()=>this.resize());this.resizeObserver.observe(wrap);this.resize();this.last=performance.now();this.running=true;this.frame=this.frame.bind(this);requestAnimationFrame(this.frame);}
 buildBoard(){const floor=box(17,.15,17,material(0xc5e5f6),1);floor.position.y=-.65;floor.receiveShadow=true;this.scene.add(floor);const bottom=box(12.5,.4,12.5,material(0x7bb3e3),.7);bottom.position.y=-.4;this.scene.add(bottom);const top=box(12.2,.18,12.2,white,.65);top.position.y=-.04;this.scene.add(top);for(let z=0;z<15;z++)for(let x=0;x<15;x++){const ci=z<7?(x<7?0:1):(x<7?3:2);const field=box(.72,.04,.72,material(PALETTE[ci],.4),.01);field.position.set((x-7)*.72,.09,(z-7)*.72);this.scene.add(field);}
for(let c=0;c<4;c++){const mat=material(PALETTE[c]);const [x,z]=baseCenters[c];const base=box(3.15,.18,3.15,mat,.45);base.position.set(x,.13,z);this.scene.add(base);const rim=box(2.91,.05,2.91,material(new T.Color(PALETTE[c]).lerp(new T.Color(0xffffff),.22)),.36);rim.position.set(x,.31,z);this.scene.add(rim);
for(let p=0;p<2;p++){const socket=new T.Mesh(new T.CylinderGeometry(.52,.52,.025,40),material(new T.Color(PALETTE[c]).multiplyScalar(.75)));const pos=basePosition(c,p);socket.position.set(pos.x,.38,pos.z);socket.receiveShadow=true;this.scene.add(socket);const ring=new T.Mesh(new T.TorusGeometry(.53,.022,8,48),material(new T.Color(PALETTE[c]).lerp(new T.Color(0xffffff),.4)));ring.rotation.x=Math.PI/2;ring.position.copy(socket.position);ring.position.y+=.03;this.scene.add(ring);}}
TRACK.forEach((co,i)=>{const t=box(.675,.16,.675,white,.065);const pos=tilePoint(co);t.position.set(pos.x,.02,pos.z);this.scene.add(t);const c=Math.floor(i/13);const mark=new T.Mesh(new T.CircleGeometry(.18,24),material(PALETTE[c]));mark.rotation.x=-Math.PI/2;mark.position.set(pos.x,.187,pos.z);this.scene.add(mark);if(i%13===0){const a=new T.Mesh(new T.RingGeometry(.23,.255,24),material(PALETTE[c]));a.rotation.x=-Math.PI/2;a.position.set(pos.x,.19,pos.z);this.scene.add(a);}});
HOMES.forEach((lane,c)=>lane.forEach((co,i)=>{const t=box(.675,.16,.675,material(new T.Color(PALETTE[c]).lerp(new T.Color(0xffffff),.15)),.065);const pos=tilePoint(co);t.position.set(pos.x,.02,pos.z);this.scene.add(t);const dot=new T.Mesh(new T.CircleGeometry(.06+i*.008,16),white);dot.rotation.x=-Math.PI/2;dot.position.set(pos.x,.188,pos.z);this.scene.add(dot);}));
const hub=new T.Mesh(new T.CylinderGeometry(1.09,1.12,.23,64),material(0xc5e3f7));hub.position.y=.13;hub.receiveShadow=true;this.scene.add(hub);const center=new T.Mesh(new T.CylinderGeometry(.85,.85,.035,64),material(0x2889ee));center.position.y=.27;this.scene.add(center);
const flag=new T.Group();const pole=new T.Mesh(new T.CylinderGeometry(.025,.025,.7,8),white);pole.position.y=.7;flag.add(pole);for(let y=0;y<2;y++)for(let x=0;x<3;x++){const sq=box(.13,.13,.02,(x+y)%2?navy:white,.005);sq.position.set(.08+x*.13,.82-y*.13,0);flag.add(sq);}flag.rotation.y=-.2;this.scene.add(flag);
// Miniature runway edge lights and airport tower stay outside the track.
for(let i=-5;i<=5;i+=1.25){for(const z of [-5.9,5.9]){const lamp=new T.Mesh(new T.SphereGeometry(.055,8,8),new T.MeshStandardMaterial({color:0xffe8a3,emissive:0xffcc55,emissiveIntensity:.6}));lamp.position.set(i,.22,z);this.scene.add(lamp);}}
const tower=new T.Group();const stem=box(.4,1,.4,white,.05);tower.add(stem);const cabin=box(.85,.4,.85,glass,.12);cabin.position.y=1;tower.add(cabin);const roof=box(.95,.08,.95,material(0x328be1),.12);roof.position.y=1.4;tower.add(roof);tower.position.set(-5.7,.15,-4.6);this.scene.add(tower);}
 setGame(game){this.game=game;this.cosmeticTrails.clear();for(const plane of this.planes)this.scene.remove(plane);this.planes=[];for(const p of game.active){for(let i=0;i<2;i++){const plane=makePlane(p.color);plane.userData.piece=i;plane.position.copy(planePosition(p.color,i,p.pieces[i]));if(p.pieces[i]<0)plane.position.y=.43;plane.rotation.y=[Math.PI/2,Math.PI,-Math.PI/2,0][p.color];this.scene.add(plane);this.planes.push(plane);}}this.setSelectable([]);}
 sync(game){this.game=game;for(const plane of this.planes){const {color,piece}=plane.userData;plane.position.copy(planePosition(color,piece,game.players[color].pieces[piece]));if(game.players[color].pieces[piece]<0)plane.position.y=.43;plane.userData.body.rotation.set(0,0,0);plane.userData.body.scale.set(1,1,1);}}
 setSelectable(keys){this.selectable=keys;for(const p of this.planes)p.userData.marker.visible=keys.includes(`${p.userData.color}:${p.userData.piece}`);}
 click(e){if(e.button!==0)return;const r=this.renderer.domElement.getBoundingClientRect();this.pointer.set((e.clientX-r.left)/r.width*2-1,-((e.clientY-r.top)/r.height)*2+1);this.ray.setFromCamera(this.pointer,this.camera);const hit=this.ray.intersectObjects(this.planes,true);for(const h of hit){let p=h.object;while(p&&!this.planes.includes(p))p=p.parent;if(p&&this.selectable.includes(`${p.userData.color}:${p.userData.piece}`)){this.onSelect(p.userData.piece);return;}}}
 resize(){const w=this.wrap.clientWidth,h=this.wrap.clientHeight;if(!w||!h)return;this.renderer.setSize(w,h);this.effectCanvas.width=w;this.effectCanvas.height=h;this.camera.aspect=w/h;const aspect=w/h;this.camera.position.set(0,aspect<1?21:17.7,aspect<1?16.4:13.8);this.camera.lookAt(0,0,0);this.camera.updateProjectionMatrix();}
 tween(ms,update){if(this.reduced){update(1);return Promise.resolve();}return new Promise(resolve=>this.anims.push({start:performance.now(),ms,update,resolve}));}
 async move(result,onBump){this.setSelectable([]);const p=this.planes.find(p=>p.userData.color===result.color&&p.userData.piece===result.piece);const steps=[];for(let i=result.from+1;i<=result.to;i++)steps.push(planePosition(result.color,result.piece,i));if(!steps.length)return;for(const target of steps){const start=p.position.clone(),duration=this.reduced?0:Math.max(65,Math.min(150,1150/steps.length));const angle=Math.atan2(target.x-start.x,target.z-start.z)+Math.PI;p.rotation.y=angle;await this.tween(duration,t=>{p.position.lerpVectors(start,target,t);p.position.y+=Math.sin(t*Math.PI)*.25;p.userData.body.rotation.z=Math.sin(t*Math.PI)*.08;const owner=this.game?.players?.[result.color];if(owner?.member)this.cosmeticTrails.emit(owner.flightTrail,`${result.color}:${result.piece}`,p.position,performance.now(),this.reduced);});}p.userData.body.rotation.z=0;
if(result.captured.length){onBump?.();this.burst(p.position);await Promise.all(result.captured.map(async v=>{const target=this.planes.find(x=>x.userData.color===v.color&&x.userData.piece===v.piece);const start=target.position.clone(),end=basePosition(v.color,v.piece);end.y=.43;await this.tween(1050,t=>{const ease=1-(1-t)**2;target.position.lerpVectors(start,end,ease);target.position.y+=Math.sin(t*Math.PI)*2.4;target.userData.body.rotation.z=t*Math.PI*4;target.userData.body.scale.set(1+.16*Math.sin(t*Math.PI),1-.18*Math.sin(t*Math.PI),1);});target.userData.body.rotation.z=0;target.userData.body.scale.set(1,1,1);}));}}
 burst(pos){if(this.reduced)return;for(let i=0;i<16;i++){const m=new T.Mesh(new T.SphereGeometry(.04+Math.random()*.05,8,6),new T.MeshBasicMaterial({color:i%3?0xffffff:0xffd050,transparent:true}));m.position.copy(pos);m.position.y+=.35;this.scene.add(m);this.particles.push({mesh:m,start:performance.now(),velocity:new T.Vector3((Math.random()-.5)*2.5,1+Math.random()*2,(Math.random()-.5)*2.5)});}}
 drawNames(){const width=this.effectCanvas.width,height=this.effectCanvas.height,entries=[];for(const plane of this.planes){const {color,piece,body}=plane.userData,point=plane.position.clone();point.y+=.95+(body?.position.y||0);point.project(this.camera);if(point.z<-1||point.z>1)continue;entries.push({key:`${color}:${piece}`,seat:color,name:this.game?.players?.[color]?.name,grade:planeMembershipGrade(this.game?.players?.[color]),color:'#'+PALETTE[color].toString(16).padStart(6,'0'),x:(point.x+1)*width/2,y:(1-point.y)*height/2});}return drawPlaneNames(this.effectContext,entries,{width,height,fontSize:Math.min(13,Math.max(10,width/75)),maxWidth:Math.min(116,Math.max(62,width/9))});}
 frame(now){if(!this.running)return;const dt=Math.min(.05,(now-this.last)/1000);this.last=now;for(const p of this.planes){if(!this.reduced)p.userData.propeller.rotation.z+=dt*5;if(!this.reduced&&this.anims.length===0)p.userData.body.position.y=Math.sin(now*.002+p.userData.color)*.018;p.userData.marker.material.opacity=.65+Math.sin(now*.007)*.25;}
this.anims=this.anims.filter(a=>{const t=Math.min(1,(now-a.start)/a.ms);a.update(t);if(t===1){a.resolve();return false;}return true;});this.particles=this.particles.filter(p=>{const age=(now-p.start)/1000;p.mesh.position.addScaledVector(p.velocity,dt);p.velocity.y-=dt*3;p.mesh.material.opacity=Math.max(0,1-age);if(age>1){this.scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();return false;}return true;});this.renderer.render(this.scene,this.camera);this.effectContext.clearRect(0,0,this.effectCanvas.width,this.effectCanvas.height);this.cosmeticTrails.draw(this.effectContext,p=>{const v=new T.Vector3(p.x,p.y,p.z).project(this.camera);return{x:(v.x+1)*this.effectCanvas.width/2,y:(1-v.y)*this.effectCanvas.height/2};},Math.min(this.effectCanvas.width/15,this.effectCanvas.height/12),now,this.reduced);this.drawNames();requestAnimationFrame(this.frame);}
}
